{"results": [{"id": "FAM:SF-CHT-025", "label": "Study family SF-CHT-025: Play-type labeling audit: OTHER/DRIVE foul leakage", "score": 1.366, "reached_via": ["request matches the question or hypothesis of FAM:SF-CHT-025 (0.78)"], "attributes": {"observed_research_question": "Play-type labeling audit: OTHER/DRIVE foul leakage", "auto_outcome_status": "artifact", "observed_hypothesis": "Play-type PPP differences are real efficiency, not labeling/foul artifacts.", "observed_result": "OTHER: 36% end in fouls, PPP inflated (FOUL_BUCKET). DRIVE: 12pp below foul benchmark (FOUL_LEAK). PNR shows 22% foul rate. Only 335 of 50,668 possessions (0.7%) map to a real play type via initiation_type.", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "OTHER PPP inflated by 36% foul endings; DRIVE 12pp below foul benchmark; initiation_type maps 0.7%.", "observed_sample_and_power": "50,668 possessions in the initiation_type check", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Per-PT diagnostic of foul-ending share vs PPP; initiation_type mapping.", "observed_verdict": "artifact_found"}, "relationships": []}, {"id": "FAM:SF-APPA-035", "label": "Study family SF-APPA-035: Relative-structure single-game validation BOS vs OKC", "score": 1.276, "reached_via": ["FAM:SF-APPA-063 auto_related_family (repeat_order_unknown) FAM:SF-APPA-035"], "attributes": {"observed_research_question": "Relative-structure single-game validation BOS vs OKC", "auto_outcome_status": "untestable", "observed_hypothesis": "Model's top-ranked play types score above team average in a held-out game.", "observed_result": "BOS rho 0.200, top-3 n/a, bottom-3 1/3; OKC rho 0.543, top-3 2/2, lift +0.308, bottom-3 1/3.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "One game; 5-6 PTs per team with 4-35 possessions.", "observed_sample_and_power": "1 game", "auto_validation_status": "same_pipeline_validation; evidence: APPA-035: 'one holdout game 0022400946; spearman of predicted vs actual pt ppp (pt'", "observed_method": "One holdout game 0022400946; Spearman of predicted vs actual PT PPP (PTs >=3 poss); top-3/bottom-3 hits.", "observed_verdict": "inconclusive", "observed_failure_type": "A_unanswerable", "observed_notes": "NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-063"}]}, {"id": "FAM:SF-APPM-044", "label": "Study family SF-APPM-044: Live-blog game replays: LP BEST/AVOID tier accuracy", "score": 0.901, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPM-044 (0.79)"], "attributes": {"observed_research_question": "Live-blog game replays: LP BEST/AVOID tier accuracy", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Pre-game LP BEST/AVOID tiers predict in-game play-type PPP (scored only on BEST/AVOID, not OK).", "observed_result": "0042500104 and 0042500173: Final 0-0, no classified possessions. 0042500101 DET 96-ORL 108: DET 2/3 (67%), ORL 2/4 (50%); ORL AVOID share 50/79 (63%). 0042500111 BOS 123-PHI 90: BOS 3/4 (75%), PHI 2/3 (67%). 0042500114 B [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Two of six replays had no classified possessions; remaining games mixed 50-75% tier accuracy with frequent AVOID live-overrides (model wrong, engine caught it).", "observed_sample_and_power": "n=6 games; scored cells 3-6 BEST/AVOID per team"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPA-050", "label": "Study family SF-APPA-050: Superstar sequential suppression: opponent play before the star", "score": 0.895, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-050 (0.78)", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.73); FAM:SF-APPA-050 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Superstar sequential suppression: opponent play before the star", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "A specific opponent play type on the preceding possession suppresses each star's next-possession PPP relative to that star's baseline.", "observed_result": "PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 to 0.884, d=-0.294, n_after=95; B. Beal d=-0.345 n=32; C. Holmgren d=-0.222 n=52). Other tops: TRANSITION (A. Davis -0.058), POST_UP (N. Jokic -0.075), PULL_ [cut; read_family for the full text]", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No multiplicity correction; n_after is 32-95 for several PUTBACK cells vs thousands of baseline possessions.", "observed_sample_and_power": "30 stars; min n_after=30", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}]}, {"id": "FAM:SF-APPM-022", "label": "Study family SF-APPM-022: Superstar suppression profiles (incl. Q5c sequential triggering)", "score": 0.895, "reached_via": ["FAM:SF-APPA-050 auto_related_family (repeated_by_later_family) FAM:SF-APPM-022", "FAM:SF-APPA-050 auto_related_family (repeat_of_earlier_family) FAM:SF-APPM-022"], "attributes": {"observed_research_question": "Superstar suppression profiles (incl. Q5c sequential triggering)", "auto_outcome_status": "inconclusive", "observed_hypothesis": "Specific opposing lineups, defenders, play types and preceding opponent play types suppress star efficiency.", "observed_result": "Q5c verdict 'rank-1 suppressor varies meaningfully across players'; e.g. Jokic after opp POST_UP 1.1271 (-0.0675, SE +/-0.0500, n=480); Curry forced POST_UP -0.209.", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "Rank-1 deltas mostly within 1-2 SE with no multiple-comparison control; OTHER artifact flagged in doc.", "observed_sample_and_power": "SE per cell reported", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "inconclusive", "observed_failure_type": "E_unclear", "observed_notes": "NOT_RECORDED", "auto_confidence": "medium (0.65)"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-050"}]}, {"id": "FAM:SF-APPA-063", "label": "Study family SF-APPA-063: Holdout play-type rank validation (LAYER_AUDIT)", "score": 0.889, "reached_via": ["request matches the question or hypothesis of FAM:SF-APPA-063 (0.77)", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.73); FAM:SF-APPA-063 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Holdout play-type rank validation (LAYER_AUDIT)", "auto_outcome_status": "supported", "observed_hypothesis": "Pre-game PT PPP ranking from training data correlates with actual efficiency ranking in held-out games.", "observed_result": "Median rho +0.539 (IQR +0.245 to +0.750); 62.4% rho>0.4; 88.4% rho>0; 10.5% rho<0. Top-3 median hit 100%; >=2/3 hits 78.9%; median lift +0.4261 PPP; 90.8% positive lift. Bottom-3 median suppression 66.7%. MAE cited in la [cut; read_family for the full text]", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "Doc caveat: top-3 lift partly reflects league-wide high-efficiency PTs (CUT, PUTBACK, TRANSITION); 10.5% of rows the model misleads (rho<0).", "observed_sample_and_power": "908 game-team rows; 454 games"}, "relationships": [{"rel": "auto_has_risk", "node": "RISK:DRIFT_NONSTATIONARITY"}, {"rel": "auto_related_family", "node": "FAM:SF-APPA-035"}]}, {"id": "FAM:SF-APPA-058", "label": "Study family SF-APPA-058: Season stability of top suppressors and negative teammate pairs", "score": 0.85, "reached_via": ["request matches RQC:RQC-044 (0.73); FAM:SF-APPA-058 auto_addresses_question RQC:RQC-044", "FAM:SF-APPA-050 auto_related_family (record_link_extends) FAM:SF-APPA-058"], "attributes": {"observed_research_question": "Season stability of top suppressors and negative teammate pairs", "auto_outcome_status": "rejected", "observed_hypothesis": "Each star's top sequential suppressor is stable across seasons, and some teammate X->Y sequences have large negative premiums.", "observed_result": "2/30 (7%) stable (>=75% same top suppressor): D. Mitchell PUTBACK 75%, L. James POST_UP 75%. Negative: J. Tatum->K. Porzingis DRIVE->SPOT_UP -0.444 n=31; Giannis->Lillard DRIVE->PNR -0.263 n=31; J. Brown->J. Tatum SPOT_U [cut; read_family for the full text]", "auto_failure_mechanism": "B_powered_null (adequately powered null result)", "observed_failure_evidence": "Only 2/30 stars meet the 75% same-top-suppressor stability rule.", "observed_sample_and_power": "30 stars x 4 seasons; min n=20/cell", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_verdict": "null"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:small_sample"}, {"rel": "auto_has_risk", "node": "RISK:SAMPLE_SIZE_POWER"}]}, {"id": "FAM:SF-APPM-058", "label": "Study family SF-APPM-058: PNR shot-level season rates vs possession labels", "score": 0.594, "reached_via": ["request matches RQC:RQC-069 (0.76); FAM:SF-APPM-058 auto_addresses_question RQC:RQC-069", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.73); FAM:SF-APPM-058 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "PNR shot-level season rates vs possession labels", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "PBP-derived shot-level PNR rates sit in a realistic band (script notes possession-level rates will be higher) and vary by team as expected.", "observed_result": "2024-25 shot-level PNR share of half-court shots ranges from OKC 7.567% (498/6581) and BOS 7.854% to IND 13.824% (856/6192) and NYK 11.959%. ATL 11.361%, DEN 11.404%, PHX 10.232% (bh 7.050 / roll 3.181).", "auto_failure_mechanism": "E_unclear (mechanism unclear from the records)", "observed_failure_evidence": "No pass/fail gate in the output; rates are a calibration input for PBPProxyPNR (later logs show calibrated PNR ~17.9-19.6% of possessions).", "observed_sample_and_power": "30 teams, half_court_shots ~5994-6581", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPM-014"}]}, {"id": "FAM:SF-PAP-096", "label": "Study family SF-PAP-096: Play-type classifier assisted-flag leak (SPOT_UP 100% makes)", "score": 0.586, "reached_via": ["request matches RQC:RQC-098 (0.75); FAM:SF-PAP-096 auto_addresses_question RQC:RQC-098", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.73); FAM:SF-PAP-096 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Play-type classifier assisted-flag leak (SPOT_UP 100% makes)", "auto_outcome_status": "artifact", "observed_hypothesis": "Possession-level play types from PBP contain unbiased predictive structure.", "observed_result": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20", "auto_failure_mechanism": "C_artifact (apparent effect produced by a construction, selection or labelling flaw)", "observed_failure_evidence": "assisted flag on makes only produced SPOT_UP 2.83 PPP", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED", "observed_method": "Sequence-level PPP by inferred play type before rewriting play_type_inferrer.py.", "observed_verdict": "artifact_found", "observed_failure_type": "C_artifact", "observed_notes": "Engineering discovery that poisoned simulation. May overlap APP slices."}, "relationships": []}, {"id": "FAM:SF-APPA-005", "label": "Study family SF-APPA-005: Defensive scheme change within game and across games (inferred labels)", "score": 0.578, "reached_via": ["request matches RQC:RQC-030 (0.73); FAM:SF-APPA-005 auto_addresses_question RQC:RQC-030", "request matches DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions (0.73); FAM:SF-APPA-005 auto_uses_dataset DS:Play_type_initiation_records_Neo4j_INITIATED_edges_play_type_possessions"], "attributes": {"observed_research_question": "Defensive scheme change within game and across games (inferred labels)", "auto_outcome_status": "untestable", "observed_hypothesis": "Playoff defenses change scheme within games and between games, especially after the opponent ran a play type heavily.", "observed_result": "Within-game change 319/523 (61.0%); cross-game change 298/440 (67.7%); 103/104 units (99.0%) and 52/52 series show a change; transition matrices near-uniform.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Doc caveat: inferred label cannot separate real defensive adjustment from offense executing differently; near-uniform transition matrices consistent with label noise.", "observed_sample_and_power": "523 cells; 440 pairs", "auto_validation_status": "no_validation_recorded; evidence: NOT_RECORDED"}, "relationships": [{"rel": "auto_limited_by", "node": "LIM:label_or_classification_error"}, {"rel": "auto_has_risk", "node": "RISK:LABEL_ERROR"}]}], "n_results": 10}

